const messages = { en, fr, ar };
const LanguageContext = createContext(null);
export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => languages[localStorage.getItem("pos_language")] ? localStorage.getItem("pos_language") : "en");
  useEffect(() => { localStorage.setItem("pos_language", language); document.documentElement.lang = language; document.documentElement.dir = languages[language].direction; }, [language]);
  const value = useMemo(() => ({ language, languages, setLanguage, t: (key) => messages[language][key] || en[key] || key }), [language]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}
export function useLanguage() { const context = useContext(LanguageContext); if (!context) throw new Error("useLanguage must be used inside LanguageProvider"); return context; }
